run_query_body:
let mut res: Vec<OutRow> = Vec::new();
if t.n > 0 && u.n > 0 {
    proof {
        reveal_with_fuel(hit_count, 3);
        reveal_with_fuel(hits_with, 3);
        reveal_with_fuel(out_copies, 3);
        assert(t.n == 1);
        assert(u.n == 1);
    }
    let hit = t.k[0] == u.k[0];
    if hit {
        let a = t.a[0];
        res.push(OutRow { a: a });
    }
    proof {
        reveal_with_fuel(hit_count, 3);
        reveal_with_fuel(hits_with, 3);
        reveal_with_fuel(out_copies, 3);
        if hit {
            assert(u.k@[0] == t.k@[0]);
            assert(exists_1(t, u, 0));
            assert(row_hit(t, u, 0));
            assert(out_key(res@[0]) == proj_key(t, u, 0));
        } else {
            assert(!exists_1(t, u, 0));
        }
    }
}
else {
    proof {
        reveal_with_fuel(hit_count, 3);
        reveal_with_fuel(hits_with, 3);
        reveal_with_fuel(out_copies, 3);
        assert(t.n == 0 || u.n == 0);
        if t.n == 0 {
            assert(hit_count(t, u, 0) == 0);
        } else {
            assert(!exists_1(t, u, 0));
        }
    }
}
res
